CASH_COMPONENTS=[]

def followup_view(inputs, prior):
    packet=inputs.get('twentysixth_period_followup')
    if packet is None:return None
    if packet['version']!=1 or packet['content_digest']!=digest({k:v for k,v in packet.items()if k!='content_digest'}):raise ValueError('twentysixth period packet changed')
    if prior is None or prior['counts']['after']!=146 or packet['prior_digest']!=digest(prior):raise ValueError('twentysixth period prior changed')
    market=inputs['current_extension']['market_inputs']
    if packet['market_digest']!=digest(market):raise ValueError('twentysixth period market changed')
    sources={s['announcement_id']:s for s in packet['sources']}
    if len(sources)!=28 or len(packet['sources'])!=28 or set(sources)!=set(SOURCE_BINDINGS):raise ValueError('twentysixth period source set changed')
    if packet['visual_read']!=VISUAL:raise ValueError('twentysixth period visual scope changed')
    for aid,s in sources.items():
        if {k:s.get(k)for k in SOURCE_BINDINGS[aid]}!=SOURCE_BINDINGS[aid]or not s['protected_gate_passed']:raise ValueError('twentysixth period source binding changed')
        if s['published_on']>'2026-11-19':raise ValueError('twentysixth period future source')
        if set(s['selected_pages'])!={str(n)for n in range(1,s['pages']+1)}or len(s['page_hashes'])!=s['pages']:raise ValueError('twentysixth period pages missing')
        for n,t in s['selected_pages'].items():
            if sha256(t.encode()).hexdigest()!=s['page_hashes'][int(n)-1]:raise ValueError('twentysixth period page changed')
    for row in FINANCIAL:
        if D(row['nine_month_yuan'])-D(row['h1_yuan'])!=D(row['quarter_yuan']):raise ValueError('quarter arithmetic changed')
        if row['reported_quarter_yuan'] is not None and D(row['quarter_yuan'])!=D(row['reported_quarter_yuan']):raise ValueError('quarter direct mismatch')
        for aid,n,keys in [(row['h1_source'],row['h1_page'],['h1_yuan']),(row['q3_source'],row['q3_page'],['nine_month_yuan']+(['reported_quarter_yuan']if row['reported_quarter_yuan']is not None else []))]:
            text=sources[aid]['selected_pages'][str(n)].replace(',','').replace(' ','').replace('\n','')
            if any(row[k]not in text for k in keys):raise ValueError('financial source binding changed')
    for r in VISUAL:
        source=sources[r['announcement_id']]
        if source['sha256']!=r['source_sha256'] or source['page_hashes'][r['page']-1]!=r['page_text_sha256'] or not r['verified']:raise ValueError('visual binding changed')
    from st_regime_comparison import build
    windows=event_windows(market,build(market)['daily'],list(sources.values()),allow_nontraded=True,allow_missing=True)
    if digest(windows)!=packet['event_windows_digest']:raise ValueError('twentysixth period windows changed')
    if packet['quote_reviews']!=QUOTE_REVIEWS:raise ValueError('quote reviews changed')
    review_map={(r['aid'],r['requested_days']):r for r in QUOTE_REVIEWS}
    if len(review_map)!=len(QUOTE_REVIEWS):raise ValueError('duplicate quote review')
    for group in windows:
        for window in group['windows']:
            review=review_map.get((group['aid'],window['requested_days']))
            if window['stock_pct'] is None:
                if review is not None:raise ValueError('nontraded quote review')
                window.update(stock_quote_check='not_calculable',stock_quote_boundary='端点无成交或缺价，收益保留空值。')
                continue
            if review is None or (review['symbol'],review['anchor'],review['through'],review['primary_return_pct'])!=(group['symbol'],window['anchor'],window['through'],window['stock_pct']):raise ValueError('quote window binding changed')
            if D(review['primary_return_pct'])-D(review['cross_return_pct'])!=D(review['difference_pp']):raise ValueError('quote difference changed')
            window.update(stock_quote_check=review['status'],stock_quote_boundary='本窗口端点跨渠道一致。' if review['status']=='matched' else '主源值，跨源待核；复权报价差异未解决，不据此精确比较超额收益。',cross_return_pct=review['cross_return_pct'],cross_difference_pp=review['difference_pp'])
            if review['status']!='matched':
                window.update(primary_stock_pct=window['stock_pct'],stock_pct=None,stock_quote_boundary='报价口径冲突，暂不认证收益；两源异值保留。')
    if packet['cashflow_components']!=CASH_COMPONENTS:raise ValueError('cashflow scope changed')
    for r in CASH_COMPONENTS:
        if not r['visual_verified']:raise ValueError('cashflow visual scope changed')
        for metric,values in r['metrics'].items():
            if D(values['nine_months'])-D(values['H1'])!=D(values['Q3_calculated']):raise ValueError('cashflow arithmetic changed')
            for aid,pages,key in [(r['H1_source'],r['H1_pages'],'H1'),(r['Q3_source'],r['Q3_pages'],'nine_months')]:
                text=''.join(sources[aid]['selected_pages'][str(n)]for n in pages).replace(',','')
                if values[key] not in text:raise ValueError('cashflow source binding changed')
        if D(r['metrics']['operating_inflow']['Q3_calculated'])-D(r['metrics']['operating_outflow']['Q3_calculated'])!=D(r['Q3_net']):raise ValueError('cashflow net changed')
    result={'through': '2026-11-19', 'title': '摘帽、处罚、基金备案和现金变化，分别改变了什么？', 'answer': '四通正式摘帽后仍要读季度更正与经营亏损；利达正式处罚不等内控缺陷解除，拟控制权变更尚未完成。正平补材及募资未还约束仍在；智知基金备案是程序进展，归母盈利、扣非亏损与现金流出需要一起看。', 'counts': {'files': 28, 'new_files': 28, 'reused_files': 0, 'pages': 856, 'new_pages': 856, 'viewed_pages': 29, 'initial_coverage': 146, 'complete_windows': 72, 'unfinished_windows': 12, 'stock_endpoint_gaps': 1}, 'boundary': '100条期间目录完整。28份856页实际核29页，不认证全文；84窗口72满12未满，80股票收益跨源一致、3冲突留空、1端点缺价。16财务衔接15当季直接披露1现金差额。重合公告窗口不当独立案例，不认证公告净影响。', 'method_promotions': 0}
    result.update(chains=CHAINS,financial_bridge=FINANCIAL,cashflow_components=CASH_COMPONENTS,phase_comparisons=[],event_windows=windows,sources=[{k:v for k,v in s.items()if k not in ["raw_item","selected_pages","page_hashes"]}for s in sources.values()])
    return result
